import { useState, useCallback, useEffect } from 'react';
import { DocumentList } from './components/DocumentList';
import { QuestionPanel } from './components/QuestionPanel';
import { DocumentDetail } from './components/DocumentDetail';
import { ConversationHistory } from './components/ConversationHistory';
import { StatusBar } from './components/StatusBar';
import { ResetDataButton } from './components/ResetDataButton';
import { Document, AppStatus, FeedbackRating, QAHistory } from '../shared/types';

type View = 'conversation' | 'document';

const headerButton = (active: boolean) => ({
  padding: '6px 14px',
  background: active ? '#533483' : '#0f3460',
  color: '#e0e0e0',
  border: '1px solid #1a1a4e',
  borderRadius: '4px',
  cursor: 'pointer',
  fontSize: '13px',
});

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>({
    documentsLoaded: 0,
    indexStatus: 'idle',
    lastActivity: '',
  });
  const [view, setView] = useState<View>('conversation');
  const [history, setHistory] = useState<QAHistory[]>([]);
  const [ratings, setRatings] = useState<Record<string, FeedbackRating>>({});
  const [pendingQuestion, setPendingQuestion] = useState<string | null>(null);
  const [askError, setAskError] = useState<string | null>(null);

  const refreshDocuments = useCallback(async () => {
    try {
      const docs = await window.knowledgeBase.documents.list();
      setDocuments(docs);
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Failed to refresh documents:', err);
    }
  }, []);

  /** Loads the persisted Q&A history and feedback ratings. */
  const refreshConversation = useCallback(async () => {
    try {
      const [items, feedback] = await Promise.all([
        window.knowledgeBase.qa.history(),
        window.knowledgeBase.feedback.list(),
      ]);
      setHistory(items);
      setRatings(Object.fromEntries(feedback.map(f => [f.answerId, f.rating])));
    } catch (err) {
      console.error('Failed to load conversation:', err);
    }
  }, []);

  useEffect(() => {
    refreshDocuments();
    refreshConversation();
  }, [refreshDocuments, refreshConversation]);

  const handleImport = useCallback(async () => {
    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
  }, []);

  const handleReset = useCallback(async () => {
    setSelectedDoc(null);
    setView('conversation');
    setAskError(null);
    await Promise.all([refreshDocuments(), refreshConversation()]);
  }, [refreshDocuments, refreshConversation]);

  const handleSelectDocument = useCallback((doc: Document) => {
    setSelectedDoc(doc);
    setView('document');
  }, []);

  const handleClearHistory = useCallback(async () => {
    try {
      await window.knowledgeBase.qa.clearHistory();
    } catch (err) {
      console.error('Clear history failed:', err);
    }
    await refreshConversation();
  }, [refreshConversation]);

  const handleAskQuestion = useCallback(async (question: string) => {
    setView('conversation');
    setAskError(null);
    setPendingQuestion(question);
    try {
      await window.knowledgeBase.qa.ask(question);
      await refreshConversation();
      // Refresh status after Q&A
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Q&A failed:', err);
      setAskError('Could not answer that question. Please try again.');
    } finally {
      setPendingQuestion(null);
    }
  }, [refreshConversation]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <header style={{
        padding: '12px 20px',
        background: '#16213e',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
        <div style={{ display: 'flex', gap: '8px' }}>
          <button
            type="button"
            aria-pressed={view === 'conversation'}
            onClick={() => setView('conversation')}
            style={headerButton(view === 'conversation')}
          >
            Conversation
          </button>
          <button type="button" onClick={refreshDocuments} style={headerButton(false)}>
            Refresh
          </button>
          <ResetDataButton onReset={handleReset} />
        </div>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        {/* Left panel: Document list */}
        <div style={{
          width: '280px',
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{
            padding: '10px 16px',
            borderBottom: '1px solid #0f3460',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}>
            <span style={{ fontSize: '13px', fontWeight: 500, color: '#a0a0c0' }}>
              Documents ({documents.length})
            </span>
            <button
              onClick={handleImport}
              style={{
                padding: '4px 10px',
                background: '#533483',
                color: '#fff',
                border: 'none',
                borderRadius: '3px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              + Import
            </button>
          </div>
          <DocumentList
            documents={documents}
            onSelect={handleSelectDocument}
            selectedId={selectedDoc?.id ?? null}
          />
        </div>

        {/* Right panel: conversation (Q&A history) or document detail, above the question box */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          <div style={{ flex: 1, overflow: 'auto', padding: '20px' }}>
            {view === 'document' && selectedDoc ? (
              <DocumentDetail document={selectedDoc} />
            ) : (
              <ConversationHistory
                history={history}
                ratings={ratings}
                pendingQuestion={pendingQuestion}
                error={askError}
                onClearHistory={handleClearHistory}
              />
            )}
          </div>

          <QuestionPanel onAsk={handleAskQuestion} disabled={pendingQuestion !== null} />
        </div>
      </div>

      <StatusBar status={appStatus} />
    </div>
  );
}
