import { makeServices, quietLogs, tempDir } from './helpers';

// Capture what the preload exposes and what it invokes.
const exposed: Record<string, any> = {};
const invoke = vi.fn(async (..._args: unknown[]) => undefined);
vi.mock('electron', () => ({
  contextBridge: { exposeInMainWorld: (key: string, api: unknown) => { exposed[key] = api; } },
  ipcRenderer: { invoke: (...args: unknown[]) => invoke(...args) },
}));

beforeAll(async () => {
  await import('../src/preload/preload');
});

/** Fake ipcMain that records handlers so tests can call them like the renderer would. */
function fakeIpcMain() {
  const handlers = new Map<string, (...args: any[]) => any>();
  return {
    handlers,
    ipcMain: { handle: (channel: string, fn: (...args: any[]) => any) => handlers.set(channel, fn) } as any,
    call: (channel: string, ...args: unknown[]) => {
      const fn = handlers.get(channel);
      if (!fn) throw new Error(`No handler for ${channel}`);
      return fn({}, ...args);
    },
  };
}

function wire() {
  quietLogs();
  vi.spyOn(Math, 'random').mockReturnValue(0);
  const services = makeServices(tempDir());
  const ipc = fakeIpcMain();
  registerIpcHandlers(ipc.ipcMain, services as Services);
  return { ...ipc, services };
}

