// Drives the real Electron app over the Chrome DevTools Protocol.
// withApp() launches the built app (dist/) with a given user-data dir, waits until the
// renderer has window.knowledgeBase, runs `fn({ evaluate, waitFor, reload, send })` (send = raw CDP call), then quits the app.
// Calling withApp() twice with the same dataDir is a real app restart.
// Requires Node's WebSocket: run scenarios with `node --experimental-websocket`.
import { spawn } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function connect(port) {
  for (let i = 0; i < 60; i++) {
    try {
      const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
      const page = targets.find((t) => t.type === 'page');
      if (page) {
        const ws = new WebSocket(page.webSocketDebuggerUrl);
        await new Promise((resolve, reject) => {
          ws.addEventListener('open', resolve);
          ws.addEventListener('error', reject);
        });
        return ws;
      }
    } catch {
      // app not up yet
    }
    await sleep(500);
  }
  throw new Error(`No Electron page on port ${port}`);
}

export async function withApp({ dataDir, port = 9361 }, fn) {
  const env = { ...process.env };
  delete env.NODE_OPTIONS; // Electron rejects --openssl-legacy-provider
  const electronBin = path.join(root, 'node_modules', '.bin', 'electron');
  const child = spawn(electronBin, ['.', `--remote-debugging-port=${port}`, `--user-data-dir=${dataDir}`], {
    cwd: root,
    env,
    stdio: ['ignore', 'ignore', 'ignore'],
  });
  const exited = new Promise((r) => child.on('exit', r));

  let ws;
  try {
    ws = await connect(port);
    let nextId = 1;
    const send = (method, params) =>
      new Promise((resolve) => {
        const id = nextId++;
        ws.addEventListener('message', function onMsg(ev) {
          const msg = JSON.parse(ev.data);
          if (msg.id === id) {
            ws.removeEventListener('message', onMsg);
            resolve(msg);
          }
        });
        ws.send(JSON.stringify({ id, method, params }));
      });

    const evaluate = async (expression) => {
      const msg = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
      if (msg.result?.exceptionDetails) {
        const d = msg.result.exceptionDetails;
        throw new Error(`In-page error: ${d.exception?.description ?? d.text}`);
      }
      return msg.result?.result?.value;
    };

    const waitFor = async (expression, timeoutMs = 10000) => {
      const start = Date.now();
      while (Date.now() - start < timeoutMs) {
        try {
          if (await evaluate(expression)) return true;
        } catch {
          // page navigating
        }
        await sleep(100);
      }
      throw new Error(`Timed out waiting for: ${expression}`);
    };

    const ready = `document.readyState === 'complete' && typeof window.knowledgeBase === 'object' && !!document.querySelector('header')`;
    await waitFor(ready);

    const reload = async () => {
      await send('Runtime.evaluate', { expression: 'location.reload()' });
      await sleep(300);
      await waitFor(ready);
    };

    return await fn({ evaluate, waitFor, reload, send });
  } finally {
    ws?.close();
    child.kill();
    await exited; // the profile lock must be released before a restart
  }
}

// Helpers injected into the page to drive the UI like a user would.
export const pageHelpers = `
  window.__e2e = {
    byLabel: (label) => Array.from(document.querySelectorAll('[aria-label="' + label + '"]')),
    setInput: (el, value) => {
      const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
      setter.call(el, value);
      el.dispatchEvent(new Event('input', { bubbles: true }));
    },
    sleep: (ms) => new Promise((r) => setTimeout(r, ms)),
  };
  true;
`;

export function report(name, checks) {
  let failed = 0;
  for (const [label, ok, detail] of checks) {
    if (!ok) failed++;
    console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${detail !== undefined ? `  -> ${JSON.stringify(detail)}` : ''}`);
  }
  console.log(failed ? `${name}: ${failed} check(s) FAILED` : `${name}: all ${checks.length} checks passed`);
  if (failed) process.exitCode = 1;
}
// E2E for feature reset-all-data, against the built app (run `npm run build` first).
// Usage: node --experimental-websocket scripts/e2e/reset-all-data.mjs
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { withApp, pageHelpers, report } from './app-session.mjs';

const dataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-e2e-reset-'));
const docs = ['design-notes.md', 'meeting-summary.txt', 'retrieval-plan.md'].map((f) => path.resolve('data/sample-documents', f));
const checks = [];

const counts = `(async () => ({
  documents: (await window.knowledgeBase.documents.list()).length,
  history: (await window.knowledgeBase.qa.history()).length,
  feedback: (await window.knowledgeBase.feedback.list()).length,
  indexed: (await window.knowledgeBase.indexing.status()).currentIndexed,
}))()`;
const populate = `(async () => {
  for (const d of ${JSON.stringify(docs)}) await window.knowledgeBase.documents.import(d);
  await window.knowledgeBase.indexing.start();
  const a = await window.knowledgeBase.qa.ask('What is the architecture design?');
  await window.knowledgeBase.feedback.submit(a.id, 'up');
  return true;
})()`;
const isEmpty = (c) => c.documents === 0 && c.history === 0 && c.feedback === 0 && c.indexed === 0;

try {
  await withApp({ dataDir }, async ({ evaluate, waitFor, reload }) => {
    // 1. Through the bridge.
    await evaluate(populate);
    const before = await evaluate(counts);
    checks.push(['populated: 3 docs, history, feedback, index', before.documents === 3 && before.history === 1 && before.feedback === 1 && before.indexed === 3, before]);
    await evaluate(`window.knowledgeBase.app.reset()`);
    const after = await evaluate(counts);
    checks.push(['app.reset() empties documents, qa.history, feedback and index', isEmpty(after), after]);

    // 2. Through the UI: the button asks first; Cancel deletes nothing; confirming deletes everything.
    await evaluate(populate);
    await reload(); // UI picks up the documents
    await evaluate(pageHelpers);
    await waitFor(`document.body.innerText.includes('Documents (3)')`);
    await evaluate(`__e2e.byLabel('Reset all data')[0].click(); true`);
    await waitFor(`!!document.querySelector('[role=alertdialog]')`);
    const dialog = await evaluate(`document.querySelector('[role=alertdialog]').innerText`);
    const afterOpen = await evaluate(counts);
    checks.push(['clicking "Reset all data" opens a confirmation dialog and deletes nothing yet',
      /Reset all data\?/.test(dialog) && afterOpen.documents === 3, { dialog, afterOpen }]);
    await evaluate(`[...document.querySelectorAll('[role=alertdialog] button')].find(b => b.textContent === 'Cancel').click(); true`);
    await waitFor(`!document.querySelector('[role=alertdialog]')`);
    const afterCancel = await evaluate(counts);
    checks.push(['Cancel closes the dialog and keeps the data', afterCancel.documents === 3 && afterCancel.history === 1 && afterCancel.feedback === 1, afterCancel]);

    await evaluate(`__e2e.byLabel('Reset all data')[0].click(); true`);
    await waitFor(`__e2e.byLabel('Confirm reset all data').length === 1`);
    await evaluate(`__e2e.byLabel('Confirm reset all data')[0].click(); true`);
    await waitFor(`!document.querySelector('[role=alertdialog]') && document.body.innerText.includes('Documents (0)')`);
    const afterUi = await evaluate(counts);
    checks.push(['confirming resets everything and the UI shows the empty state', isEmpty(afterUi), afterUi]);
  });

  // 3. Restart: still empty.
  await withApp({ dataDir }, async ({ evaluate }) => {
    const c = await evaluate(counts);
    const text = await evaluate(`document.body.innerText.includes('Documents (0)')`);
    checks.push(['after restart everything is still empty', isEmpty(c) && text, c]);
  });
} finally {
  fs.rmSync(dataDir, { recursive: true, force: true });
}
report('reset-all-data e2e', checks);
