          <button type="button" onClick={refreshDocuments} style={headerButton(false)}>
            Refresh
          </button>
          <ResetDataButton onReset={handleReset} />
        </div>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        {/* Left panel: Document list */}
        <div style={{
          width: '280px',
