import { Document } from '../../shared/types';

interface Props {
  /** Documents to show (already filtered by the search query). */
  documents: Document[];
  /** How many documents exist in total, regardless of the search. */
  totalCount: number;
  query: string;
  onQueryChange: (query: string) => void;
  onSelect: (doc: Document) => void;
  selectedId: string | null;
}

export function DocumentList({ documents, totalCount, query, onQueryChange, onSelect, selectedId }: Props) {
  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
      <div style={{ padding: '8px 16px', borderBottom: '1px solid #0f3460' }}>
        <input
          type="search"
          aria-label="Search documents"
          placeholder="Search documents"
          value={query}
          onChange={e => onQueryChange(e.target.value)}
          style={{
            width: '100%',
            boxSizing: 'border-box',
            padding: '6px 8px',
            background: '#1a1a2e',
            color: '#e0e0e0',
            border: '1px solid #0f3460',
            borderRadius: '3px',
            fontSize: '12px',
          }}
        />
      </div>
      {totalCount === 0 ? (
        <div style={{ padding: '20px 16px', color: '#666', fontSize: '13px', textAlign: 'center' }}>
          No documents imported yet.
          <br />
          <span style={{ fontSize: '11px', color: '#555' }}>
            Import documents to get started.
          </span>
        </div>
      ) : documents.length === 0 ? (
        <div role="status" style={{ padding: '20px 16px', color: '#666', fontSize: '13px', textAlign: 'center' }}>
          No documents match "{query.trim()}".
        </div>
      ) : (
        <div style={{ flex: 1, overflow: 'auto' }}>
          {documents.map(doc => (
            <div
              key={doc.id}
              data-document-id={doc.id}
              onClick={() => onSelect(doc)}
              style={{
                padding: '10px 16px',
                cursor: 'pointer',
                borderBottom: '1px solid #0f3460',
                background: selectedId === doc.id ? '#0f3460' : 'transparent',
                transition: 'background 0.15s',
              }}
            >
              <div style={{ fontSize: '13px', fontWeight: 500 }}>{doc.title}</div>
              <div style={{ fontSize: '11px', color: '#888', marginTop: '2px' }}>
                {doc.status === 'indexed' ? 'Indexed ' : ''}
                {(doc.size / 1024).toFixed(1)} KB
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

